        if (raw.startsWith("+")) {
            e164 = "+" + digits;
        } else {
            if (digits.startsWith("0")) {
                digits = digits.substring(1);
            }
            e164 = "+61" + digits;
        }
        int digitCount = e164.length() - 1;
        if (digitCount < 8 || digitCount > 15) {
